package net.officefloor.hq.app.statement;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.person.PersonController.PersonView;
import net.officefloor.hq.app.person.PersonService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/people/{personId}/statements")
@Validated
public class StatementController {

    /** A statement just taken: the person as they now show, and their claims as it bound them. */
    public record TakenView(PersonView person, List<ClaimView> claims) {
    }

    /** The statement form: the day the statement is taken as of; left out, the sheet's today. */
    public record StatementForm(LocalDate asOf) {
    }

    private final StatementService service;
    private final SheetService sheets;
    private final PersonService people;

    public StatementController(StatementService service, SheetService sheets, PersonService people) {
        this.service = service;
        this.sheets = sheets;
        this.people = people;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public TakenView take(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody(required = false) StatementForm form) {
        StatementService.Taken taken = service.take(sheetId.trim(), user.trim(), personId,
                form == null ? null : form.asOf());
        return new TakenView(PersonView.of(taken.person(), taken.summary(), sheets.today(sheetId.trim()),
                people.clashing(sheetId.trim(), taken.person())),
                taken.claims().stream().map(ClaimView::of).toList());
    }

    /** Cancel the person's last statement. */
    @DeleteMapping("/last")
    public TakenView cancelLast(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        StatementService.Taken cancelled = service.cancelLast(sheetId.trim(), user.trim(), personId);
        return new TakenView(PersonView.of(cancelled.person(), cancelled.summary(), sheets.today(sheetId.trim()),
                people.clashing(sheetId.trim(), cancelled.person())),
                cancelled.claims().stream().map(ClaimView::of).toList());
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A statement taken of a person: their due-total on the day it was taken as of, and how many of their
 *  claims counted then. */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /** The sheet's today when the statement was taken. */
    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    @Column(name = "taken_by", nullable = false)
    private String takenBy;

    /** The person's due-total then; null when it was n/a. */
    @Column(name = "due_total", precision = 14, scale = 2)
    private BigDecimal dueTotal;

    @Column(name = "claims", nullable = false)
    private int claims;

    /** The earlier day the statement was taken as of; null when it was taken as of the sheet's today. */
    @Column(name = "as_of")
    private LocalDate asOf;

    /** The sheet's today when the statement was cancelled; null while it stands. */
    @Column(name = "cancelled_on")
    private LocalDate cancelledOn;

    /** Whether the statement came to its person with a merge or a transfer (it was another person's). */
    @Column(name = "carried", nullable = false)
    private boolean carried;

    protected Statement() {
    }

