243	@Service
244	public class StatementService {
245	
246	    /** A statement just taken: the person, what their statements now come to, and their claims
247	     *  (newest first) as the statement bound them. */
248	    public record Taken(Person person, StatementSummary summary, List<Claim> claims) {
