274	    /** What each person's statements on the sheet come to, by person id; a person with none is
275	     *  missing. */
276	    @Transactional(readOnly = true)
277	    public Map<Long, StatementSummary> summaries(String sheetId) {
278	        return statements.findBySheetIdAndCancelledOnIsNullOrderByIdAsc(sheetId).stream()
279	                .collect(Collectors.groupingBy(Statement::getPersonId,
280	                        Collectors.collectingAndThen(Collectors.toList(), StatementSummary::of)));
281	    }
