283	    /** What each person's statements on the sheet came to at the end of a day: those taken while the
284	     *  sheet's today was on or before it and not cancelled by then, by person id; a person with none
285	     *  is missing. */
286	    @Transactional(readOnly = true)
287	    public Map<Long, StatementSummary> summaries(String sheetId, LocalDate day) {
288	        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
289	                .filter(s -> s.stoodOn(day))
290	                .collect(Collectors.groupingBy(Statement::getPersonId,
291	                        Collectors.collectingAndThen(Collectors.toList(), StatementSummary::of)));
292	    }
