294	    /** What one person's statements come to. */
295	    @Transactional(readOnly = true)
296	    public StatementSummary summary(String sheetId, long personId) {
297	        return StatementSummary.of(statements.findBySheetIdAndPersonIdAndCancelledOnIsNullOrderByIdAsc(sheetId, personId));
298	    }
299	
300	    /** Take a statement of a person: record their due-total now and bind each of their claims that
301	     *  counts in the live totals to the rate figure it has now, leaving out any late charge and the floor; any other
302	     *  claim (one that does not count, a deferred one, or an open unbound one dated within one of their
303	     *  holds) is unbound. */
304	    @Transactional
305	    public Taken take(String sheetId, String user, long personId) {
306	        return take(sheetId, user, personId, null);
307	    }
308	
309	    /** Take a statement of a person as of a day (null: the sheet's today) on or before the sheet's
310	     *  today: the sheet as it stood at the end of that day (see {@link History}) stands in for it as
311	     *  it is now, that day for its today. Their due-total then is recorded, and each claim of theirs
312	     *  that counted in the live totals then is bound to the rate figure it had then; every other claim
313	     *  of theirs is unbound. Refused when the day is after the sheet's today, or when the person was
314	     *  not on the sheet yet then. */
315	    @Transactional
316	    public Taken take(String sheetId, String user, long personId, LocalDate asOf) {
317	        LocalDate today = sheets.today(sheetId);
318	        if (asOf != null && asOf.isAfter(today)) {
319	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
320	                    "A statement cannot be taken as of a day after the sheet's today");
321	        }
322	        Person person = people.lockByIdAndSheetId(personId, sheetId)
323	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
324	        History.SheetAsOf then = asOf == null ? null : history.asOf(sheetId, asOf);
325	        Person was = then == null ? person : then.person(personId)
326	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
327	                        "The person was not on the sheet yet on that day"));
328	        List<Claim> bound = rollup.tracking(sheetId, user, () -> {
329	            List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
330	            Dues.Basis basis = then == null ? dues.now(sheetId) : then.basis();
331	            List<Claim> counted = Dues.live(was, then == null ? theirs : then.claimsOf(personId), basis.today());
332	            BigDecimal dueTotal = dues.dueTotal(basis, was, counted);
333	            Map<Long, Claim> countedById = counted.stream().collect(Collectors.toMap(Claim::getId, c -> c));
334	            for (Claim claim : theirs) {
335	                Claim figured = countedById.get(claim.getId());
336	                if (figured != null) {
337	                    claim.bind(true, dues.bindable(basis, was, figured), dues.bindsNa(basis, was, figured));
338	                } else {
339	                    claim.bind(false, null);
340	                }
341	            }
342	            claims.saveAllAndFlush(theirs);
343	            statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted.size(), asOf));
344	            audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
345	                    + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.setScale(2).toPlainString())
346	                    + " claims=" + counted.size() + (asOf != null ? " asof=" + asOf : ""));
347	            return theirs;
348	        });
349	        return new Taken(person, summary(sheetId, personId), bound);
350	    }
351	
352	    /** Cancel a person's last statement: only a steward may, and only when one was taken. The claims
353	     *  it bound become live again (a figure an earlier statement bound is not restored), and the
354	     *  statement before it, if any, becomes their last. The cancelled statement is kept, marked with
355	     *  the sheet's today, so the sheet as of an earlier day still shows it. Their last is their own
356	     *  last statement, or, having none, the last one carried to them by a merge or a transfer. */
357	    @Transactional
358	    public Taken cancelLast(String sheetId, String user, long personId) {
359	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
360	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can cancel a statement");
361	        }
362	        Person person = people.lockByIdAndSheetId(personId, sheetId)
363	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
364	        List<Statement> taken = statements.findBySheetIdAndPersonIdAndCancelledOnIsNullOrderByIdAsc(sheetId, personId);
365	        if (taken.isEmpty()) {
366	            throw new ResponseStatusException(HttpStatus.CONFLICT, "No statement has been taken of this person");
367	        }
368	        Statement last = StatementSummary.last(taken);
369	        List<Claim> unbound = rollup.tracking(sheetId, user, () -> {
370	            List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
371	            theirs.forEach(claim -> claim.bind(false, null));
372	            claims.saveAllAndFlush(theirs);
373	            last.cancel(sheets.today(sheetId));
374	            statements.saveAndFlush(last);
375	            audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
376	                    + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().setScale(2).toPlainString()));
377	            return theirs;
378	        });
379	        return new Taken(person, summary(sheetId, personId), unbound);
380	    }
381	}
