389	/** What a person's statements come to: how many were taken (those carried to them with a merge or a
390	 *  transfer too), and the last one's due-total (null when
391	 *  it was n/a) and date (the day it was taken as of); both null when none was taken; and every one of
392	 *  them, oldest first by its date (those of a day in the order they were taken). */
393	public record StatementSummary(int count, BigDecimal lastDueTotal, LocalDate lastTakenOn, List<Line> lines) {
394	
395	    public static final StatementSummary NONE = new StatementSummary(0, null, null, List.of());
396	
397	    /** One statement: its date (the day it was taken as of) and its due-total (null when it was n/a). */
398	    public record Line(LocalDate date, BigDecimal dueTotal) {
399	    }
400	
401	    /** The summary of one person's statements, given in the order they were taken. */
402	    public static StatementSummary of(List<Statement> statements) {
403	        if (statements.isEmpty()) {
404	            return NONE;
405	        }
406	        Statement last = last(statements);
407	        List<Line> lines = statements.stream()
408	                .sorted(Comparator.comparing(Statement::getStatedOn))
409	                .map(st -> new Line(st.getStatedOn(), st.getDueTotal()))
410	                .toList();
411	        return new StatementSummary(statements.size(), last.getDueTotal(), last.getStatedOn(), lines);
412	    }
413	
414	    /** A person's last statement, of theirs given in the order they were taken: the last of their
415	     *  own, or, having none, the last one carried to them; null when there are none. */
416	    public static Statement last(List<Statement> statements) {
417	        Statement last = null;
418	        for (Statement s : statements) {
419	            if (last == null || !s.isCarried() || last.isCarried()) {
420	                last = s;
421	            }
422	        }
423	        return last;
424	    }
425	}
