444	/** The due figures of claims, and the due-totals of people, at the rates on a sheet: as they are
445	 *  now, or on any other {@link Basis} (such as the sheet as it stood at the end of an earlier day). */
446	@Service
447	public class Dues {
448	
449	    /** What a sheet's figures are worked out from: its today, its dated settings and its rates. */
450	    public interface Basis {
451	
452	        /** The day that stands in for the sheet's today. */
453	        LocalDate today();
454	
455	        /** The floor in force on a day. */
456	        BigDecimal floor(LocalDate day);
457	
458	        /** The late percent in force on a day. */
459	        BigDecimal latePct(LocalDate day);
460	
461	        /** The cap in force on the basis's today; null when there is none. */
462	        BigDecimal cap();
463	
464	        /** The policy date in force: the one set, or else the basis's today. */
465	        LocalDate policyDateInForce();
466	
467	        /** The rounding mode in force on a day; null when none is (blank, or never set). */
468	        RoundingMode rounding(LocalDate day);
469	
470	        /** The rates of a grade, the latest from-date first and the one with none last. */
471	        List<Rate> rates(String grade);
472	
473	        /** The grace days of a grade in force on a day; 0 when none is (blank, or never set). */
474	        int grace(String grade, LocalDate day);
475	
476	        /** The rate of a grade in force on a day: the sheet's own, or else, when it has none in force
477	         *  on it, its ancestors' (see {@link #inherited}); empty when none is. */
478	        default Optional<Rate> rateInForce(String grade, LocalDate day) {
479	            return RateRepository.inForce(rates(grade), day).or(() -> inherited(grade, day));
480	        }
481	
482	        /** The rate of a grade in force on a day on the sheet's parent, or else its parent's, up to
483	         *  three levels up; empty when none is (or the sheet has no parent). */
484	        default Optional<Rate> inherited(String grade, LocalDate day) {
485	            return Optional.empty();
486	        }
487	
488	        /** The rate of a grade that applies to a claim: the one in force on the claim's date (as
489	         *  {@link #rateInForce}), each rate taken as the newest of its versions that applies to the
490	         *  claim (see Rate#appliesTo) and passed over when none does; empty when none applies. */
491	        default Optional<Rate> rateFor(String grade, Claim claim) {
492	            return RateRepository.inForce(applying(rates(grade), claim), claim.getDate())
493	                    .or(() -> inheritedFor(grade, claim));
494	        }
495	
496	        /** The rate of a grade that applies to a claim on the sheet's parent, or else its parent's, up
497	         *  to three levels up (see {@link #rateFor}); empty when none does. */
498	        default Optional<Rate> inheritedFor(String grade, Claim claim) {
499	            return Optional.empty();
500	        }
501	
502	        /** The older versions of a rate, the newest first; none when they are not kept. */
503	        default List<Rate> olderVersions(Rate rate) {
504	            return List.of();
505	        }
506	
507	        /** Rates given latest from-date first, each as the newest of its versions that applies to the
508	         *  claim, leaving out those none of whose versions does. */
509	        default List<Rate> applying(List<Rate> latestFirst, Claim claim) {
510	            List<Rate> applying = new ArrayList<>();
511	            for (Rate rate : latestFirst) {
512	                if (rate.appliesTo(claim)) {
513	                    applying.add(rate);
514	                } else {
515	                    olderVersions(rate).stream().filter(v -> v.appliesTo(claim)).findFirst()
516	                            .ifPresent(applying::add);
517	                }
518	            }
519	            return applying;
520	        }
521	    }
