536	    /** The sheet as it is now: its today, its settings and its rates. */
537	    public Basis now(String sheetId) {
538	        return new Basis() {
539	            @Override
540	            public LocalDate today() {
541	                return sheets.today(sheetId);
542	            }
543	
544	            @Override
545	            public BigDecimal floor(LocalDate day) {
546	                return sheets.floor(sheetId, day);
547	            }
548	
549	            @Override
550	            public BigDecimal latePct(LocalDate day) {
551	                return sheets.latePct(sheetId, day);
552	            }
553	
554	            @Override
555	            public BigDecimal cap() {
556	                return sheets.cap(sheetId);
557	            }
