628	    /** A rate figure with its late charge (taken as open or not) on top, then at least the sheet's
629	     *  floor in force on the claim's date (a correction has no floor); null when the figure is. */
630	    private BigDecimal floored(Basis basis, Person person, Claim claim, BigDecimal figure, boolean open) {
631	        if (figure == null) {
632	            return null;
633	        }
634	        BigDecimal charged = figure.add(lateCharge(basis, person, claim, figure, open));
635	        return claim.isCorrection() ? charged : charged.max(basis.floor(claim.getDate()));
636	    }
637	
638	    /** The rate figure a statement binds a claim to: the one its person's last statement bound it to,
639	     *  or else its live rate figure (a pending claim is bound like any other claim that counts);
640	     *  never the late charge, which keeps following the sheet's today, nor the floor, which is applied
641	     *  last. Null when there is none, or when the statement bound it to n/a. */
642	    public BigDecimal bindable(String sheetId, Person person, Claim claim) {
643	        return bindable(now(sheetId), person, claim);
644	    }
645	
646	    /** The rate figure a statement binds a claim to on a basis (see {@link #bindable(String, Person, Claim)}). */
647	    public BigDecimal bindable(Basis basis, Person person, Claim claim) {
648	        if (bound(claim) && (claim.getStatedDue() != null || claim.isStatedNa())) {
649	            return claim.getStatedDue();
650	        }
651	        return due(basis, person, claim);
652	    }
653	
654	    /** Whether a statement binds a claim to n/a: its person's last statement bound it to n/a, or
655	     *  else it has no bound figure and no live due: no rate applies to it on its date (for the
656	     *  person's grade on that date), none ever having been set or the one that would having ended. */
657	    public boolean bindsNa(String sheetId, Person person, Claim claim) {
658	        return bindsNa(now(sheetId), person, claim);
659	    }
660	
661	    /** Whether a statement binds a claim to n/a on a basis (see {@link #bindsNa(String, Person, Claim)}). */
662	    public boolean bindsNa(Basis basis, Person person, Claim claim) {
663	        if (bound(claim) && (claim.getStatedDue() != null || claim.isStatedNa())) {
664	            return claim.isStatedNa();
665	        }
666	        return due(basis, person, claim) == null;
667	    }
668	
669	    /** Whether a claim is bound by its person's last statement now (a pending claim is too). */
670	    private static boolean bound(Claim claim) {
671	        return claim.isStated();
672	    }
673	
674	    /** The day a claim's lateness is counted from: its due-by (fixed when it was made) plus the grace
675	     *  days in force on the claim's date for its person's grade in force on that date. */
676	    public LocalDate lateFrom(Basis basis, Person person, Claim claim) {
677	        return claim.getDueBy().plusDays(basis.grace(person.gradeOn(claim.getDate()), claim.getDate()));
678	    }
679	
680	    /** Whether a claim is overdue on the sheet's today: it is open (or pending), not deferred on it,
681	     *  and its {@link #lateFrom} is before it. */
682	    public boolean overdue(String sheetId, Person person, Claim claim) {
683	        return overdue(now(sheetId), person, claim);
684	    }
685	
686	    /** Whether a claim is overdue on a basis's today (see {@link #overdue(String, Person, Claim)}). */
687	    public boolean overdue(Basis basis, Person person, Claim claim) {
688	        LocalDate today = basis.today();
689	        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && lateFrom(basis, person, claim).isBefore(today);
690	    }
691	
692	    /** The late charge on a claim taken as open (or pending) or not, overdue on the sheet's today (its {@link #lateFrom}
693	     *  before today; a correction has none): for each full 30 days it is overdue, the late percent in force on
694	     *  that boundary (its late-from plus 30, 60, 90 ... days) of its figure plus the charges of the boundaries
695	     *  before it (the charge compounds), rounded to two decimals by the claim's
696	     *  {@link #rounding}, the charges added up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not overdue,
697	     *  or its late charge is waived. */
698	    private BigDecimal lateCharge(Basis basis, Person person, Claim claim, BigDecimal figure, boolean open) {
699	        BigDecimal none = BigDecimal.ZERO.setScale(2);
700	        LocalDate today = basis.today();
701	        if (!open || claim.isCorrection() || claim.isWaived() || claim.isDeferredOn(today)) {
702	            return none;
703	        }
704	        LocalDate lateFrom = lateFrom(basis, person, claim);
705	        long periods = ChronoUnit.DAYS.between(lateFrom, today) / 30;
706	        if (periods <= 0) {
707	            return none;
708	        }
709	        RoundingMode rounding = rounding(basis, claim);
710	        BigDecimal charge = none;
711	        for (long n = 1; n <= periods; n++) {
712	            BigDecimal pct = basis.latePct(lateFrom.plusDays(30 * n));
713	            if (pct.signum() != 0) {
714	                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
715	            }
716	        }
717	        return charge;
718	    }
719	
720	    /** Whether a claim of the person counts in the live totals on the sheet's today: it counts, it is
721	     *  not deferred on that day, and it is not an open (or pending) claim, unbound by a statement,
722	     *  dated within one of the person's holds or of a person retired on that day. */
723	    public static boolean countsLive(Person person, Claim claim, LocalDate today) {
724	        return claim.getStatus().counts() && !claim.isDeferredOn(today) && !leftOut(person, claim, today);
725	    }
726	
727	    /** Whether a claim of the person counts in a period's totals: by the status it had at the end of
728	     *  the period's last day (see Claim#statusOn) it counts, and the live rules do not leave it out:
729	     *  it is not deferred on the sheet's today, and it is not a claim open (or pending) now,
730	     *  unbound by a statement, dated within one of the person's holds or of a person retired on the
731	     *  sheet's today. */
732	    public static boolean countsAsOf(Person person, Claim claim, LocalDate end, LocalDate today) {
733	        ClaimStatus then = claim.statusOn(end);
734	        return then != null && then.counts() && !claim.isDeferredOn(today) && !leftOut(person, claim, today);
735	    }
736	
737	    /** Whether the live rules leave a claim of the person out: it is open (or pending) now, unbound
738	     *  by a statement, and dated within one of the person's holds or the person is retired on the
739	     *  sheet's today. */
740	    private static boolean leftOut(Person person, Claim claim, LocalDate today) {
741	        return claim.getStatus().isOpen() && !claim.isStated()
742	                && (person.isHeldOn(claim.getDate()) || person.isRetiredOn(today));
743	    }
744	
745	    /** The claims of a person that count in the live totals on the sheet's today. */
746	    public static List<Claim> live(Person person, List<Claim> theirs, LocalDate today) {
747	        return theirs.stream().filter(c -> countsLive(person, c, today)).toList();
748	    }
749	
750	    /** A person's due-total: the sum of the figures of their claims that count, at most the sheet's
751	     *  cap in force on its today; null (n/a) when their grade on the sheet's today has no rate on it and no counting claim
752	     *  has a figure (one fixed, or a live due at the grade in force on its date). */
753	    public BigDecimal dueTotal(String sheetId, Person person, List<Claim> theirs) {
754	        return dueTotal(now(sheetId), person, theirs);
755	    }
756	
757	    /** A person's due-total on a basis (see {@link #dueTotal(String, Person, List)}). */
758	    public BigDecimal dueTotal(Basis basis, Person person, List<Claim> theirs) {
759	        List<BigDecimal> figures = theirs.stream().filter(c -> c.getStatus().counts())
760	                .map(c -> figure(basis, person, c)).filter(d -> d != null).toList();
761	        LocalDate today = basis.today();
762	        boolean rated = basis.rateInForce(person.gradeOn(today), today).isPresent();
763	        if (!rated && figures.isEmpty()) {
764	            return null;
765	        }
766	        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
767	        BigDecimal cap = basis.cap();
768	        return cap == null ? sum : sum.min(cap);
769	    }
770	
771	    /** A claim's live due at the rate that applies to it (see {@link Basis#rateFor}): the one in
772	     *  force on the claim's date, for the person's grade in force on that date, that applies to it (taken from the sheet's ancestors when it has none
773	     *  of its own in force then): amount times pct divided by 100, rounded to two decimals by the claim's {@link #rounding} (the floor is
774	     *  applied later, see {@link #floored}); null when no rate applies on that date. */
775	    private BigDecimal due(Basis basis, Person person, Claim claim) {
776	        RoundingMode rounding = rounding(basis, claim);
777	        return basis.rateFor(person.gradeOn(claim.getDate()), claim)
778	                .map(Rate::getPct)
779	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
780	                .orElse(null);
781	    }
782	
783	    /** How a claim's live figures round: by the sheet's rounding mode in force on the claim's date,
784	     *  or, when none is, half up when the date it rounds by (a correction's is that of the claim it
785	     *  corrects) is before the sheet's policy date, else half to even. */
786	    private RoundingMode rounding(Basis basis, Claim claim) {
787	        RoundingMode mode = basis.rounding(claim.getDate());
788	        if (mode != null) {
789	            return mode;
790	        }
791	        return claim.roundsBy().isBefore(basis.policyDateInForce()) ? RoundingMode.HALF_UP
792	                : RoundingMode.HALF_EVEN;
793	    }
794	}
